create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.churches (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.campuses (id uuid primary key default gen_random_uuid(), church_id uuid not null references public.churches(id) on delete cascade, name text not null, city text, state text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.church_members (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, church_id uuid not null references public.churches(id) on delete cascade, campus_id uuid not null references public.campuses(id) on delete cascade, role text not null check (role in ('DM','MEMBER')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, church_id));
alter table public.profiles enable row level security; alter table public.churches enable row level security; alter table public.campuses enable row level security; alter table public.church_members enable row level security;
create policy "profile own read" on public.profiles for select using (auth.uid() = id); create policy "profile own update" on public.profiles for update using (auth.uid() = id) with check (auth.uid() = id);
create policy "onboarding church read" on public.churches for select to authenticated using (true); create policy "onboarding campus read" on public.campuses for select to authenticated using (true); create policy "membership own read" on public.church_members for select using (auth.uid() = user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id, full_name) values (new.id, new.raw_user_meta_data ->> 'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.create_church_with_membership(p_church_name text, p_campus_name text, p_city text, p_state text) returns void language plpgsql security definer set search_path = public as $$ declare v_church uuid; v_campus uuid; begin insert into churches(name) values (p_church_name) returning id into v_church; insert into campuses(church_id,name,city,state) values(v_church,p_campus_name,p_city,p_state) returning id into v_campus; insert into church_members(user_id,church_id,campus_id,role) values(auth.uid(),v_church,v_campus,'DM'); end; $$;
create or replace function public.join_church(p_church_id uuid, p_campus_id uuid) returns void language plpgsql security definer set search_path = public as $$ begin if not exists(select 1 from campuses where id=p_campus_id and church_id=p_church_id) then raise exception 'Campus inválido'; end if; insert into church_members(user_id,church_id,campus_id,role) values(auth.uid(),p_church_id,p_campus_id,'MEMBER'); end; $$;
grant execute on function public.create_church_with_membership(text,text,text,text), public.join_church(uuid,uuid) to authenticated;
